xfs_buf_t*
xfs_buf_find(
	struct xfs_buftarg		*btp,
	struct xfs_buf_map		*map,
	int				nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t			*new_bp)
{
	xfs_buf_t		*bp;
	xfs_daddr_t		bno;
	uint			nblocks;
	int			i;

	if (nmaps == 0)
		return NULL;

	nblocks = 0;
	for (i = 0; i < nmaps; i++) {
		nblocks += XFS_BUF_MAP_SIZE(map + i);
	}

	if (nblocks == 0)
		return NULL;

	bno = XFS_BUF_MAP_BLOCK(map);
	bp = xfs_buf_find(btp, bno, nblocks, flags);
	if (bp) {
		if (XFS_BUF_ISSTALE(bp))
			xfs_buf_stale(bp);
		xfs_buf_lock(bp);
		return bp;
	}

	if ((flags & XFS_BUF_BUSY) || (flags & XFS_BUF_LOCK))
		return NULL;

	if (new_bp) {
		new_bp->b_bn = bno;
		new_bp->b_bno = bno;
		new_bp->b_bcount = nblocks;
		new_bp->b_flags = flags;
		xfs_buf_insert(new_bp, btp);
	}
	return new_bp;
}

xfs_buf_t *
xfs_buf_find(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	xfs_buf_t		*bp;
	xfs_daddr_t		blkno;
	size_t			numblks;
	struct xfs_mount	*mp = btp->bt_mount;

	blkno = map[0].bm_bn;
	numblks = 0;

	if (unlikely(nmaps <= 0)) {
		ASSERT(0);
		return NULL;
	}

	if (flags & XBF_WRITE) {
		if (xfs_sb_version_hasalign(&mp->m_sb)) {
			if (blkno & ((1 << mp->m_dalign_shift) - 1)) {
				return NULL;
			}
		}
	}

	for (int i = 0; i < nmaps; i++) {
		numblks += map[i].bm_len;
	}

	bp = xfs_buf_search(btp, map, nmaps, flags);

	if (bp) {
		if (bp->b_flags & XBF_STALE) {
			xfs_buf_stale(bp);
		}
		if (xfs_buf_islocked(bp)) {
			xfs_buf_lock(bp);
		}
		xfs_buf_hold(bp);
		return bp;
	}

	if (new_bp) {
		new_bp->b_bn = blkno;
		new_bp->b_bno = blkno;
		new_bp->b_count = numblks;
		xfs_buf_insert(new_bp, btp);
	}
	return new_bp;
}

xfs_buf_t*
xfs_buf_find(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	xfs_buf_t		*bp = NULL;
	xfs_daddr_t		blkno;
	int			error;
	int			i;

	for (i = 0; i < nmaps; i++) {
		xfs_daddr_t	start = map[i].bm_bn;
		xfs_daddr_t	end = start + map[i].bm_len;

		if (start >= end)
			continue;

		for (blkno = start; blkno < end; blkno++) {
			bp = xfs_buf_find_by_block(btp, blkno);
			if (bp)
				break;
		}

		if (bp)
			break;
	}

	if (!bp)
		return NULL;

	if (bp->b_flags & XBF_STALE) {
		error = xfs_buf_revalidate(bp);
		if (error) {
			xfs_buf_free(bp);
			return NULL;
		}
	}

	if (xfs_buf_lock(bp)) {
		xfs_buf_free(bp);
		return NULL;
	}

	if (flags & XBF_TRYLOCK && !xfs_buf_islocked(bp)) {
		xfs_buf_unlock(bp);
		xfs_buf_free(bp);
		return NULL;
	}

	if (new_bp) {
		xfs_buf_insp(btp, new_bp, bp);
	}

	return bp;
}

xfs_buf_t *
xfs_buf_find(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	xfs_buf_t		*bp;
	xfs_daddr_t		first_block;
	size_t			num_blocks = 0;
	xfs_daddr_t		block;
	int			i;

	/*
	 * Calculate the total number of blocks in the map and determine the first block.
	 */
	first_block = NULL;
	for (i = 0; i < nmaps; i++) {
		num_blocks += map[i].bm_len;
		if (i == 0)
			first_block = map[i].bm_bn;
	}

	if (!first_block)
		return NULL;

	/*
	 * Traverse the buffer tree to find a matching buffer.
	 */
	bp = xfs_buf_search(btp, map, nmaps, flags);
	if (bp) {
		/*
		 * If buffer is found, handle stale buffer case and lock.
		 */
		if (XFS_BUF_ISSTALE(bp)) {
			xfs_buf_stale(bp);
			xfs_buf_relse(bp);
			return NULL;
		}
		xfs_buf_lock(bp);
		return bp;
	}

	/*
	 * No matching buffer found; consider inserting a new one.
	 */
	if (new_bp) {
		new_bp->b_bn = first_block;
		new_bp->b_bno = first_block;
		new_bp->b_count = num_blocks;
		xfs_buf_insert(new_bp, btp);
		return new_bp;
	}

	return NULL;
}

xfs_buf_t*
xfs_btree_lookup_buffer(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	xfs_daddr_t		daddr;
	xfs_buf_t		*bp;
	int			error;
	int			i;
	int			num_segs = 0;
	int			num_bytes = 0;

	/* Calculate total number of bytes and validate mapping */
	for (i = 0; i < nmaps; i++) {
		num_segs++;
		num_bytes += map[i].bm_len;
	}

	/* Check for block number alignment and corruption */
	for (i = 0; i < nmaps; i++) {
		daddr = map[i].bm_bn;
		if (daddr < XFS_DADDR_NULL || daddr > XFS_MAX_DBLOCK)
			return NULL;
	}

	/* Traverse the red-black tree of buffers to find a matching block */
	bp = xfs_buf_find(btp, map, num_segs, flags);
	if (bp) {
		/* Handle stale buffers */
		if (xfs_buf_stale(bp)) {
			xfs_buf_free(bp);
			return NULL;
		}
		/* Lock the buffer and return it */
		xfs_buf_lock(bp);
		return bp;
	}

	/* If no match is found, insert the new buffer if provided */
	if (new_bp) {
		error = xfs_buf_insert(new_bp, btp, map, num_segs, flags);
		if (error) {
			return NULL;
		}
		return new_bp;
	}

	/* No matching buffer found */
	return NULL;
}
